/* ===================== BÀI 5 · 1971 microprocessor và máy tính cá nhân ===================== */
/* Bài 5 · 1971 microprocessor và máy tính cá nhân (CM00.05) — sinh bởi tools/author/maytinh/m05.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l5"),{id:"l5",scenarios:[{"label": "Ví dụ: 5 + 3 trên bộ cộng 4 bit", "note": "Phần nhớ lan qua ba bit liên tiếp, kết quả vừa trong 4 bit.", "steps": [{"t": "Đặt A = 0101, B = 0011", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td><\/td><td><\/td><td>0<\/td><\/tr><tr><td>A = 5<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>B = 3<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">A = 5 = 0101₂ · B = 3 = 0011₂<\/p>", "say": "<p>Bộ cộng xử lý từng bit từ phải sang trái, giống cộng có nhớ ở hệ thập phân nhưng mỗi cột chỉ có 0 và 1: 1 + 1 = 10₂ (ghi 0, nhớ 1).<\/p>"}, {"t": "Bit 0: 1 + 1 + 0 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td><\/td><td>1<\/td><td class=\"hi\">0<\/td><\/tr><tr><td>A = 5<\/td><td>0<\/td><td>1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>B = 3<\/td><td>0<\/td><td>0<\/td><td>1<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td><\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 1: 0 + 1 + 1 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td>1<\/td><td class=\"hi\">1<\/td><td>0<\/td><\/tr><tr><td>A = 5<\/td><td>0<\/td><td>1<\/td><td class=\"hi\">0<\/td><td>1<\/td><\/tr><tr><td>B = 3<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td class=\"new\">0<\/td><td>0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 2: 1 + 0 + 1 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td>1<\/td><td class=\"hi\">1<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>A = 5<\/td><td>0<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>B = 3<\/td><td>0<\/td><td class=\"hi\">0<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td class=\"new\">0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Bit 2: 1 + 0 + 1 (nhớ). Ghi bit nào và nhớ bao nhiêu?", "o": ["Ghi 0, nhớ 1", "Ghi 1, nhớ 0", "Ghi 2, nhớ 0"], "a": 0}}, {"t": "Bit 3: 0 + 0 + 1 (nhớ) = 1 → ghi 1, nhớ 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td class=\"hi\">1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>A = 5<\/td><td class=\"hi\">0<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>B = 3<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td class=\"new\">1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Kết quả: 1000₂ = 8, cờ nhớ = 0", "html": "<p class=\"mt-calc\">5 + 3 = <b>8<\/b> = 1000₂ · cờ nhớ (carry) = 0: kết quả vừa trong 4 bit<\/p>"}]}, {"label": "Ví dụ: 9 + 8 vượt 4 bit, cờ nhớ = 1", "note": "17 không vừa 4 bit: thanh ghi giữ 0001, cờ nhớ mang giá trị 16.", "steps": [{"t": "Đặt A = 1001, B = 1000", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td><\/td><td><\/td><td>0<\/td><\/tr><tr><td>A = 9<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>B = 8<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">A = 9 = 1001₂ · B = 8 = 1000₂<\/p>", "say": "<p>Bộ cộng xử lý từng bit từ phải sang trái, giống cộng có nhớ ở hệ thập phân nhưng mỗi cột chỉ có 0 và 1: 1 + 1 = 10₂ (ghi 0, nhớ 1).<\/p>"}, {"t": "Bit 0: 1 + 0 + 0 (nhớ) = 1 → ghi 1, nhớ 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td><\/td><td>0<\/td><td class=\"hi\">0<\/td><\/tr><tr><td>A = 9<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>B = 8<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">0<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td><\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 1: 0 + 0 + 0 (nhớ) = 0 → ghi 0, nhớ 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td>0<\/td><td class=\"hi\">0<\/td><td>0<\/td><\/tr><tr><td>A = 9<\/td><td>1<\/td><td>0<\/td><td class=\"hi\">0<\/td><td>1<\/td><\/tr><tr><td>B = 8<\/td><td>1<\/td><td>0<\/td><td class=\"hi\">0<\/td><td>0<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td class=\"new\">0<\/td><td>1<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 2: 0 + 0 + 0 (nhớ) = 0 → ghi 0, nhớ 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td>0<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>A = 9<\/td><td>1<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>B = 8<\/td><td>1<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td class=\"new\">0<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 3: 1 + 1 + 0 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>A = 9<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>B = 8<\/td><td class=\"hi\">1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><tr><td>Tổng<\/td><td class=\"new\">0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table>"}, {"t": "4 bit kết quả = 0001 = 1, cờ nhớ = 1", "html": "<p class=\"mt-calc\">9 + 8 = 17 = <b>1<\/b> 0001₂ → thanh ghi 4 bit giữ <b>0001<\/b>, cờ nhớ = <b>1<\/b><\/p><p class=\"mt-calc\">17 = 1 × 16 + 1: cờ nhớ có giá trị 16<\/p>", "ask": {"q": "9 + 8 = 17 không vừa 4 bit (tối đa 15). Thanh ghi 4 bit giữ giá trị nào?", "o": ["15", "1", "17"], "a": 1}, "say": "<p>Bộ cộng không “làm tròn” hay báo lỗi: nó giữ 4 bit thấp và bật cờ nhớ. Chương trình phải tự kiểm tra cờ này.<\/p>"}]}, {"label": "Ví dụ: Cộng 8 bit bằng hai lần 4 bit", "note": "0x3A + 0x2C: nửa thấp trước, nửa cao sau, kèm cờ nhớ.", "steps": [{"t": "Cần cộng 0x3A + 0x2C (58 + 44)", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Nửa cao<\/th><th scope=\"col\">Nửa thấp<\/th><\/tr><\/thead><tbody><tr><td>A = 0x3A<\/td><td>3 = 0011<\/td><td>A = 1010<\/td><\/tr><tr><td>B = 0x2C<\/td><td>2 = 0010<\/td><td>C = 1100<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">Mỗi chữ số hệ 16 ứng đúng 4 bit, nên chia số 8 bit thành hai nửa 4 bit<\/p>", "say": "<p>Bộ xử lý 4 bit không cộng được số 8 bit trong một lần. Nó cộng nửa thấp trước, rồi cộng nửa cao <b>kèm cờ nhớ<\/b>.<\/p>"}, {"t": "Lần 1: nửa thấp A + C = 22 → ghi 6, cờ nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Nửa cao<\/th><th scope=\"col\">Nửa thấp<\/th><\/tr><\/thead><tbody><tr><td>A = 0x3A<\/td><td>0011<\/td><td>1010<\/td><\/tr><tr><td>B = 0x2C<\/td><td>0010<\/td><td>1100<\/td><\/tr><tr><td>Kết quả<\/td><td>?<\/td><td class=\"new\">0110<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">10 + 12 = 22 = 16 + 6 → nửa thấp = 6 (0110), cờ nhớ = 1<\/p>", "ask": {"q": "Nửa thấp: A (10) + C (12) = 22. 4 bit kết quả và cờ nhớ là gì?", "o": ["6, cờ nhớ 1", "22, cờ nhớ 0", "2, cờ nhớ 2"], "a": 0}}, {"t": "Lần 2: nửa cao 3 + 2 + 1 (nhớ) = 6", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Nửa cao<\/th><th scope=\"col\">Nửa thấp<\/th><\/tr><\/thead><tbody><tr><td>A = 0x3A<\/td><td>0011<\/td><td>1010<\/td><\/tr><tr><td>B = 0x2C<\/td><td>0010<\/td><td>1100<\/td><\/tr><tr><td>Kết quả<\/td><td class=\"new\">0110<\/td><td>0110<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">3 + 2 + 1 = 6 → nửa cao = 6 (0110), cờ nhớ = 0<\/p>"}, {"t": "Kết quả: 0x66 = 102", "html": "<p class=\"mt-calc\">0x3A + 0x2C = <b>0x66<\/b> = 6 × 16 + 6 = <b>102<\/b> = 58 + 44 ✓<\/p>", "say": "<p>Hai lần cộng 4 bit cùng cờ nhớ cho kết quả đúng như một lần cộng 8 bit. Bộ xử lý rộng hơn làm được cùng việc trong ít lần hơn: đó là một lý do 8 bit, 16 bit, 32 bit, 64 bit lần lượt thay thế 4 bit.<\/p>"}]}, {"label": "Ví dụ: Miền giá trị 4, 8, 16 bit", "note": "Thêm 1 bit thì số giá trị gấp đôi.", "steps": [{"t": "n bit cho 2ⁿ giá trị", "html": "<p class=\"mt-calc\">Mỗi bit có 2 trạng thái → n bit có 2 × 2 × … × 2 = 2ⁿ tổ hợp<\/p>", "say": "<p>Số không dấu nhỏ nhất là 0, nên lớn nhất là 2ⁿ − 1.<\/p>"}, {"t": "4 bit: 0 … 15", "html": "<p class=\"mt-calc\">2<sup>4<\/sup> = 16 giá trị → lớn nhất 15<\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Độ rộng<\/th><th scope=\"col\">Miền giá trị không dấu<\/th><\/tr><\/thead><tbody><tr><td>4 bit<\/td><td>0 … 15<\/td><\/tr><\/tbody><\/table>"}, {"t": "8 bit: 0 … 255", "html": "<p class=\"mt-calc\">2<sup>8<\/sup> = 256 giá trị → lớn nhất 255<\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Độ rộng<\/th><th scope=\"col\">Miền giá trị không dấu<\/th><\/tr><\/thead><tbody><tr><td>4 bit<\/td><td>0 … 15<\/td><\/tr><tr><td>8 bit<\/td><td>0 … 255<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Thanh ghi 8 bit không dấu chứa được số lớn nhất là bao nhiêu?", "o": ["256", "255", "128"], "a": 1}}, {"t": "16 bit: 0 … 65 535", "html": "<p class=\"mt-calc\">2<sup>16<\/sup> = 65 536 giá trị → lớn nhất 65 535<\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Độ rộng<\/th><th scope=\"col\">Miền giá trị không dấu<\/th><\/tr><\/thead><tbody><tr><td>4 bit<\/td><td>0 … 15<\/td><\/tr><tr><td>8 bit<\/td><td>0 … 255<\/td><\/tr><tr><td>16 bit<\/td><td>0 … 65 535<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mỗi lần thêm 1 bit, miền giá trị gấp đôi. 4004 là bộ xử lý 4 bit; 8008 và 8080 là 8 bit; IBM PC dùng 8088 có thanh ghi 16 bit.<\/p>"}]}, {"label": "Ví dụ: Chữ số thập phân trong 4 bit (BCD)", "note": "Vì sao bộ xử lý 4 bit hợp với máy tính toán.", "steps": [{"t": "Một chữ số thập phân cần 4 bit", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chữ số<\/th><th scope=\"col\">4 bit<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>0000<\/td><\/tr><tr><td>5<\/td><td>0101<\/td><\/tr><tr><td>7<\/td><td>0111<\/td><\/tr><tr><td>9<\/td><td>1001<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">0–9 có 10 giá trị: 3 bit chỉ có 8 tổ hợp (không đủ), 4 bit có 16 (đủ)<\/p>", "say": "<p>Máy tính toán hiển thị số thập phân, nên thường lưu mỗi chữ số trong 4 bit: cách mã hóa BCD. Bộ xử lý 4 bit như 4004 vì vậy hợp với máy tính toán.<\/p>"}, {"t": "Số 59 trong BCD: 0101 1001", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chữ số<\/th><th scope=\"col\">5<\/th><th scope=\"col\">9<\/th><\/tr><\/thead><tbody><tr><td>4 bit<\/td><td>0101<\/td><td>1001<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">59 (BCD) = 0101 1001 · khác 59 nhị phân thuần = 0011 1011<\/p>", "ask": {"q": "Trong BCD, số 59 cần bao nhiêu nhóm 4 bit?", "o": ["1", "2", "6"], "a": 1}}, {"t": "6 tổ hợp 4 bit không dùng trong BCD", "html": "<p class=\"mt-calc\">1010, 1011, 1100, 1101, 1110, 1111 (10–15) không phải chữ số thập phân<\/p>", "say": "<p>BCD lãng phí một ít tổ hợp nhưng đổi ra chữ số để hiển thị rất đơn giản. Chương 3 sẽ so sánh các cách mã hóa số.<\/p>"}]}, {"label": "Bẫy: Quên cờ nhớ giữa hai nửa", "note": "Kết quả lệch đúng 16, giá trị của cờ nhớ.", "steps": [{"t": "Cộng nửa thấp: 6, cờ nhớ 1", "html": "<p class=\"mt-calc\">A + C = 22 → nửa thấp 0110, cờ nhớ = 1<\/p>"}, {"t": "Cộng nửa cao nhưng QUÊN cờ nhớ: 3 + 2 = 5", "html": "<p class=\"mt-calc\">3 + 2 = 5 (bỏ quên nhớ 1)<\/p>", "ask": {"q": "Nếu quên cờ nhớ khi cộng nửa cao, kết quả sai lệch bao nhiêu so với 102?", "o": ["Thiếu 1", "Thiếu 16", "Không sai"], "a": 1}}, {"t": "Kết quả sai: 0x56 = 86 (thiếu 16)", "html": "<p class=\"mt-calc\">0x56 = 5 × 16 + 6 = <b>86<\/b>, đúng phải là <b>102<\/b> · lệch 16 = giá trị của cờ nhớ<\/p>", "say": "<p>Cờ nhớ ở nửa thấp có giá trị 16 đối với số 8 bit. Bỏ quên nó là lỗi kinh điển khi cộng số nhiều phần; lệnh “cộng có nhớ” (ADC trên nhiều bộ xử lý) tồn tại để tránh lỗi này.<\/p>"}]}, {"label": "Lỗi: 15 + 1 trên thanh ghi 4 bit ra 0", "note": "Không xem cờ nhớ thì tưởng kết quả là 0.", "steps": [{"t": "Đặt A = 1111, B = 0001", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td><\/td><td><\/td><td>0<\/td><\/tr><tr><td>A = 15<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>B = 1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">A = 15 = 1111₂ · B = 1 = 0001₂<\/p>", "say": "<p>Bộ cộng xử lý từng bit từ phải sang trái, giống cộng có nhớ ở hệ thập phân nhưng mỗi cột chỉ có 0 và 1: 1 + 1 = 10₂ (ghi 0, nhớ 1).<\/p>"}, {"t": "Bit 0: 1 + 1 + 0 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td><\/td><td>1<\/td><td class=\"hi\">0<\/td><\/tr><tr><td>A = 15<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>B = 1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td><\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 1: 1 + 0 + 1 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td><\/td><td>1<\/td><td class=\"hi\">1<\/td><td>0<\/td><\/tr><tr><td>A = 15<\/td><td>1<\/td><td>1<\/td><td class=\"hi\">1<\/td><td>1<\/td><\/tr><tr><td>B = 1<\/td><td>0<\/td><td>0<\/td><td class=\"hi\">0<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td><\/td><td class=\"new\">0<\/td><td>0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 2: 1 + 0 + 1 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td>1<\/td><td class=\"hi\">1<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>A = 15<\/td><td>1<\/td><td class=\"hi\">1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>B = 1<\/td><td>0<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td><\/td><td class=\"new\">0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Bit 3: 1 + 0 + 1 (nhớ) = 2 → ghi 0, nhớ 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">bit 3<\/th><th scope=\"col\">bit 2<\/th><th scope=\"col\">bit 1<\/th><th scope=\"col\">bit 0<\/th><\/tr><\/thead><tbody><tr><td>Nhớ vào<\/td><td class=\"hi\">1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>A = 15<\/td><td class=\"hi\">1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>B = 1<\/td><td class=\"hi\">0<\/td><td>0<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>Tổng<\/td><td class=\"new\">0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Thanh ghi 4 bit = 0000, cờ nhớ = 1", "html": "<p class=\"mt-calc\">15 + 1 = 16 = 1 0000₂ → thanh ghi giữ <b>0000<\/b><\/p>", "ask": {"q": "Chương trình chỉ đọc thanh ghi 4 bit, không xem cờ nhớ. Nó thấy 15 + 1 bằng bao nhiêu?", "o": ["16", "0", "15"], "a": 1}, "say": "<p>Bộ đếm 4 bit đi 13, 14, 15 rồi quay về 0, giống đồng hồ công tơ mét quay vòng. Chương 3 sẽ học kỹ tràn số và số có dấu.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l5"),"l5",[{"kind": "num", "t": "Miền giá trị n bit", "d": "<p>Số không dấu (chỉ có 0 và số dương). Ghi kết quả ở hệ thập phân.<\/p>", "items": [{"q": "Số lớn nhất lưu được trong 4 bit?", "a": 15}, {"q": "Số lớn nhất lưu được trong 8 bit?", "a": 255}, {"q": "Số lớn nhất lưu được trong 16 bit?", "a": 65535}, {"q": "12 bit có bao nhiêu giá trị khác nhau?", "a": 4096}], "hints": ["n bit có 2ⁿ giá trị khác nhau.", "Bắt đầu từ 0 nên lớn nhất là 2ⁿ − 1.", "2⁸ = 256, 2¹² = 4 096, 2¹⁶ = 65 536."], "why": "2⁴ − 1 = 15, 2⁸ − 1 = 255, 2¹⁶ − 1 = 65 535; 12 bit có 2¹² = 4 096 giá trị (từ 0 tới 4 095)."}, {"kind": "num", "t": "Cộng trên bộ cộng 4 bit", "d": "<p>Bộ cộng 4 bit giữ 4 bit thấp và cờ nhớ (0 hoặc 1). Ghi các giá trị ở hệ thập phân.<\/p>", "items": [{"q": "9 + 8: giá trị 4 bit kết quả?", "a": 1}, {"q": "9 + 8: cờ nhớ?", "a": 1}, {"q": "12 + 3: giá trị 4 bit kết quả?", "a": 15}, {"q": "0x3A + 0x2C cộng bằng hai lần 4 bit: nửa thấp A + C cho 4 bit kết quả bằng?", "a": 6}, {"q": "0x3A + 0x2C: kết quả 8 bit cuối cùng (thập phân)?", "a": 102}], "hints": ["Nếu tổng ≥ 16 thì cờ nhớ = 1 và 4 bit kết quả = tổng − 16.", "Chữ số hệ 16: A = 10, C = 12.", "Nửa cao: 3 + 2 + cờ nhớ của nửa thấp; kết quả = nửa cao × 16 + nửa thấp."], "why": "17 = 16 + 1 → 4 bit = 1, cờ nhớ 1; 12 + 3 = 15 vừa 4 bit; 10 + 12 = 22 = 16 + 6 → nửa thấp 6, nhớ 1; nửa cao 3 + 2 + 1 = 6 → 0x66 = 102."}, {"kind": "order", "t": "Xếp các mốc theo thời gian", "d": "<p>Xếp từ sớm nhất (trên cùng) tới muộn nhất.<\/p>", "items": ["Intel 4004 được công bố", "Intel 8008 ra đời", "Intel 8080 ra đời", "Altair 8800 lên bìa tạp chí Popular Electronics", "Apple II được bán ra", "IBM PC được giới thiệu"], "hints": ["Ba chip Intel ra đời trước các máy tính dùng chúng.", "4004 là 4 bit, rồi tới hai chip 8 bit.", "Altair 1975, Apple II 1977, IBM PC 1981."], "why": "1971 4004 · 1972 8008 · 1974 8080 · 1975 Altair 8800 · 1977 Apple II · 1981 IBM PC."}]);

makeQuiz("quiz5","score5",[{"q": "Bộ vi xử lý (microprocessor) là gì?", "o": ["Một máy tính hoàn chỉnh trên một chip", "Toàn bộ khối xử lý trung tâm (CPU) nằm trên một chip", "Một chip nhớ có thể lập trình", "Một máy tính rất nhỏ cầm tay"], "a": 1, "e": "Vi xử lý chỉ là CPU; nó cần thêm bộ nhớ và mạch vào/ra mới thành máy tính. Chip gộp cả CPU, bộ nhớ và vào/ra là vi điều khiển."}, {"q": "Thanh ghi 8 bit không dấu chứa được số lớn nhất là bao nhiêu?", "o": ["256", "128", "8", "255"], "a": 3, "e": "8 bit có 2⁸ = 256 giá trị, từ 0 tới 255. Chọn 256 là nhầm số giá trị với giá trị lớn nhất."}, {"q": "Cộng 12 + 7 trên bộ cộng 4 bit. Thanh ghi kết quả và cờ nhớ là gì?", "o": ["3, cờ nhớ 1", "19, cờ nhớ 0", "15, cờ nhớ 1", "3, cờ nhớ 0"], "a": 0, "e": "12 + 7 = 19 = 16 + 3: 4 bit thấp là 0011 = 3, phần 16 chuyển thành cờ nhớ = 1. Bộ cộng không “giữ lại 15” khi tràn."}, {"q": "Vì sao IBM PC (1981) có ảnh hưởng lâu dài tới máy tính ngày nay?", "o": ["Vì là máy tính cá nhân đầu tiên", "Vì dùng bộ xử lý 4 bit", "Vì kiến trúc mở cho phép nhiều hãng làm card và máy tương thích", "Vì không cần hệ điều hành"], "a": 2, "e": "Trước IBM PC đã có Altair 8800, Apple II… Ảnh hưởng của IBM PC đến từ kiến trúc mở: linh kiện sẵn có, tài liệu công bố, khe mở rộng, tạo ra cả một hệ sinh thái máy tương thích."}, {"q": "Khác biệt chính giữa vi xử lý và vi điều khiển là gì?", "o": ["Vi điều khiển tích hợp thêm bộ nhớ và cổng vào/ra trên cùng chip", "Vi điều khiển luôn nhanh hơn", "Vi xử lý không chạy được chương trình", "Vi điều khiển không có CPU"], "a": 0, "e": "Vi điều khiển = CPU + bộ nhớ + vào/ra trên một chip, hợp với thiết bị điều khiển nhỏ. Tốc độ không phải tiêu chí phân biệt."}]);

